skill.script:
function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		addStatus(owner, Skill.PhysicalBlock_Status_WellTimed);
		hit.block += vars.var2;
	}
}

function onSkillProc(ctx) {
	if(ctx.baseSkill.isFinalAttack()) {
		ctx.dmgMult += vars.damage;
		stop();
	}
}

function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		addStatusDuration(hit.source, Skill.Root, vars.dur1);
		hit.block += vars.var2;
	}
}

function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		hit.block += vars.var2;
	}
}

function onClientStep(s) {
	if(s.kind == Steps.CheckGround) {
		if(!owner.body.grounded)
			localPlayStep(Steps.Air);
	}
}

var timeStationary = 0.0;

function onSkillProc(ctx) {
	if (!ctx.skill.isPassive()) {
		removeBuff();
	}
}

function onUpdate(dt) {
	if (ownerHero != null && ownerHero.gliding) {
		removeBuff();
	}
	if (Math.abs(owner.moveX) < 0.01 && Math.abs(owner.moveY) < 0.01) {
		timeStationary += dt;
	} else {
		timeStationary = 0;
	}

	if (timeStationary > vars.duration) {
		removeBuff();
	}
}

function removeBuff() {
	removeStatus(owner, status.kind);
}

function onInflictHit(hit) {
	if(hit.isFirstHit)
		ownerHero.gainSparkParticle(10);
}

function onInflictDamage(dmg) {
	if (dmg.skillId == Skill.SparkSurge_Mark)
		return;
	var amount = dmg.amount * vars.var1;
	addStatus(dmg.target, Skill.SparkSurge_Mark, amount);
}

function onStop(ctx) {
	for(s in getInflictedStatuses(Skill.SparkSurge_Mark)) {
		var count = s.consume();
	}
}

function onDamageEval(hit) {
	hit.dmgMult += status.stacks;
}

function onDamage(dmg) {
	if( dmg.critical ) {
		resetCooldown(Skill.Axe_Boomerang_Skill1);
	}
}

function onDamageEval(hit) {
	if( hit.target.hasStatusType(StatusType.Bleed) ) {
		hit.dmgMult += vars.var1;
	}
}

function onDamage(dmg) {
	var amount = dmg.amount * vars.var1;
	addStatus(dmg.target, Skill.Axe_Boomerang_Skill1_Status, amount);
}

function onDamageEval(hit) {
	if( rank >= 3 ) {
		hit.critDmgMult += vars.var2;
	}
}

var cd = 0.;
function onInflictDamage(dmg) {
	if (rank >= 3 && dmg.isPhysical && dmg.critical && cd <= 0) {
		setDynVal(1, vars.var2 * owner.maxHealth);
		playStep(Steps.Heal, owner);
		cd = vars.time;
	}
}
function onRegUpdate(dt) {
	if (cd > 0) {
		cd -= dt;
	}
}

function onFirstHit(h) {
	addStatus(owner, Skill.Mace_Benediction_Status);

}

function onInflictDamage(dmg) {
	if (dmg.isFirstHit && dmg.skillId == Skill.Mace_Benediction_Combo && rank >= 3) {
		if (dmg.critical) {
			addStatus(owner, Skill.Mace_Benediction_Skill1_Proc);
			resetCooldown(Skill.Mace_Benediction_Skill1);
		}
	}
	if (rank >= 2 && dmg.stepId == Steps.Hit) {
		playStep(Steps.Area, dmg.target);
	}
}

var Benediction = Skill.Mace_Benediction_Status;
var Buff = Skill.Mace_Benediction_Skill1_Status;

function onStep(s) {
	if (s.kind == Steps.Consume) {
		if (hasStatusMaxStacked(owner, Benediction))
			addStatus(owner, Buff);

		var buffStacks = owner.getStatusCount(Benediction, owner);
		owner.tryConsumeStatus(Benediction, owner);
		var refund = 0;
		if (rank >= 3) {
			for (i in 0...buffStacks) {
				if (checkProba(vars.chance)) {
					refund++;
				}
			}
		}
		if (refund > 0) {
			owner.addStatus(Benediction, refund);
		}
	}
}

function onDamageEval(hit) {
	if (rank >= 2) {
		hit.critDmgMult += vars.damage;
	}
}


function haveInstantCast() {
	return owner.getStatus(Skill.Mace_Benediction_Skill1_Proc) != null;
}

function shouldPlayInstantly() {
	return haveInstantCast();
}

function shouldHighlightSkill() {
	return haveInstantCast();
}

function onProc(ctx) {
	removeStatus(owner, Skill.Mace_Benediction_Skill1_Proc);
}

var Buff = Skill.Mace_Benediction_Passive_Status;

function onSkillProc(ctx) {
	if (ctx.isWeaponSkill) {
		removeStatus(owner, Buff);
		addStatus(owner, Buff, vars.var1);
	}
}

var Benediction = Skill.Mace_Benediction_Status;
var SelfBuff = Skill.Mace_Benediction_Passive_Status;

function onInflictDamage(dmg) {
	if (dmg.isBaseAttack) {
		playStep(Steps.Damage, dmg.target);
		if (dmg.isFirstHit) {
			consumeStatus(owner, SelfBuff, 1);
			addStatus(owner, Benediction);
		}
	}
}

function onInflictDamageEval(hit) {
	if (rank >= 3) {
		if (hit.isBaseAttack) {
			hit.critChance += sourceSkill.vars.chance;
		}
	}
}

function onFirstHit(hit) {
	if(rank >= 3) {
		reduceWeaponsCooldown(vars.time);
	}
}

function onDamageEval(hit) {
	if(rank >= 2) {
		hit.critChance += vars.var1;
	}
}

function onDamage(dmg) {
	if(dmg.critical && rank == 3) {
		addStatus(dmg.target, Skill.Sword_Start_Skill1Status);
	}
}

function onFirstHit(hit) {
	if( checkProba(vars.var1) ) {
		var sk = ownerHero.getOffhandWeaponSkill();
		if(sk != null) {
			sk.reduceCooldown(vars.time);
			if(rank >= 3) {
				playStep(Steps.MagicDamage, hit.target);
			}
		}
	}
}

function onGameBeat(beat, hit) {
	if( beat == GameBeat.AttackBlock) {
		resetCooldown(kind);
	}
	if(rank >= 3 && beat == GameBeat.BlockWellTimed) {
		addStatus(owner, Skill.Sword_Craft_Skill1_Status);
	}
}

function onDamageEval(hit) {
	if(rank >= 2) {
		hit.dmgMult += vars.var1;
	}
}

function onStart(ctx) {
	var stacks = consumeStatus(owner, Skill.Sword_Craft_Skill1_Status);
	if(stacks > 0) {
		ctx.dmgMult += stacks * vars.var3;
	}
}

function onRegUpdate(dt) {
	var count = countEnemiesInRange(vars.range);
	var apply = count >= vars.var1;
	var inCombat = owner.isInCombat;
	setStatus(owner, Skill.Sword_Craft_Passive_Status, apply && inCombat ? 1 : 0);
}

function onStop(ctx) {
	setStatus(owner, Skill.Sword_Craft_Passive_Status, 0);
}

function onGameBeat(beat, hit) {
	if(rank >= 3) {
		if(beat == GameBeat.BlockWellTimed) {
			playStep(Steps.HealArea);
		}
	}
}

function onHealEval(h) {
	if( owner.healthRatio < vars.threshold ) {
		h.critChance = 1;
	}
}

function onHit(hit) {
	if (rank >= 3) {
		addStatus(owner, Skill.Sword_Swarm_Skill1_SelfBuff);
	}
}

function onSkillProc(ctx) {
	if (ctx.baseSkill.isWeaponSkill()) {
		addStatus(owner, Skill.Sword_Swarm_Passive_Swarm);
	}
}

function onInflictDamage(dmg) {
	if( dmg.skillId == Skill.Sword_Swarm_Passive_Swarm) {
		if( checkProba(vars.chance) && rank >= 3 ) {
			addStatus(dmg.target, Skill.Sword_Swarm_Passive_Poison);
		}
		var dmg = dmg.amount;
		var amount = dmg * vars.var2;
		applyHeal(owner, amount);
 	}


}

function onGameBeat(beat, hit) {
	if(rank >= 3 && beat == GameBeat.BlockWellTimed) {
		addStatus(owner, Skill.Shield_Start_Skill1_Status);
	}
}

function onHit(hit) {
	addStatusDuration(hit.target, Skill.Stun, vars.dur1);
}

function onStart(ctx) {
	var stacks = consumeStatus(owner, Skill.Shield_Start_Skill1_Status);
	if(stacks > 0) {
		ctx.dmgMult += stacks * vars.var2;
	}
}

function onGameBeat(beat, dmg) {
	if( beat == GameBeat.AttackBlock) {
		reduceCooldown(Skill.Shield_Craft_Skill1, vars.dur1);
	}
}

var STATUS_KIND = Skill.Shield_Craft_Passive_Status;

function onRegUpdate(dt) {
	if(!isInCooldown()) {
		setStatus(owner, STATUS_KIND);
	}
}

function onReceiveDamageEval(hit) {
	if(isInCooldown()) {
		hit.dmgMult -= vars.var2;
	}
}

/*function onSkillProc(ctx) {
	if(hasStatus(owner, STATUS_KIND)) {
		if(ctx.skill.isFinalAttack()) {
			var armor = getAtb(owner, Attribute.Armor);
			var dmg = armor * vars.var1;
			ctx.dmgAdd += dmg;
			removeStatus(owner, STATUS_KIND);
			consumeCooldown();
		}
	}
}*/

function onInflictDamageEval(hit) {
	if( hasStatus(owner, Skill.Shield_Craft_Passive_Status) && hit.isFinalCombo ) {
		playStep(Steps.MagicDamage, hit.target);
		removeStatus(owner, Skill.Shield_Craft_Passive_Status);
		consumeCooldown();
	}
}

function onProc(ctx) {
	removeStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus);
	setStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus, 10);
}

function onHit(hit) {
	if( hit.stepId == Steps.Orb ) {
		consumeStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus);

		if( hasStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus) ) {
			playStep(Steps.Area);
		} else {
			var ctx = playStep(Steps.LastOrbArea);
			if (rank >= 3) {
				ctx.dmgMult += 1;
			}
		}
	}
}

function onDamage(dmg) {
	if( rank >= 3 && dmg.stepId == Steps.LastOrbArea ) {
		addStatusDuration(dmg.target, Skill.Stun, vars.dur1);
	}
}

function onGameBeat(b, hit) {
	if( b == GameBeat.AttackBlock ) {
		// Wait next frame so block doesn't trigger the block status.
		if( !hasStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed) ) {
			wait(0, () -> {
				addWaterInfusion();
			});
		}
	}
}

function onInflictHit(hit) {
	if( hit.isFinalCombo && hit.isFirstHit) {
		addWaterInfusion();
	}
}

function addWaterInfusion() {
	if( !hasStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed) ) {
		addStatus(owner, Skill.Shield_OrbitWater_P_Status);
	}
}

function onInflictDamage(dmg) {
	if( dmg.hitCount == 1 && dmg.skillId == Skill.Shield_OrbitWater_P_StatusBlockBuffed ) {
		reduceCooldown(Skill.Shield_OrbitWater_S1, vars.dur1);
	}
}

function onStacksChange() {
	if( stacks >= maxStacks ) {
		removeStatus(owner, Skill.Shield_OrbitWater_P_Status);
		addStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed);
	}

}

function onGameBeat(b,hit) {
	if( b == GameBeat.AttackBlock ) {
		playStep(Steps.Area);
		skill.stop();
	}

}

function onReceiveDamageEval(hit) {
	if (skill.isRunning() && rank >= 3 ) {
		if (hit.blockHit()) {
			playStep(Steps.Hit);
		}
	}
}

var STATUS_KIND = Skill.Shield_Firebreath_Passive_Status;

function onGameBeat(b,hit) {
	if (b == GameBeat.AttackBlock) {
		addStatus(owner, STATUS_KIND);
	}
}

function onReceiveDamage(dmg) {
	if (rank >= 3 && dmg.source != owner) {
		playStep(Steps.ReflectDamage, dmg.source);
	}
}

function onReceiveDamageEval(dmg) {
	if (rank >= 2 && dmg.isMagic) {
		dmg.dmgMult -= vars.var1;
	}
}

var firedThisStep = false;
function gainStinger(count) {
	for (i in 0...count) {
		var prevStacks = owner.getStatusCount(Skill.Spear_Goo_Combo_Status);
		var s = owner.addStatus(Skill.Spear_Goo_Combo_Status);
		if (s.stacks > prevStacks) {
			playStep(Steps.Projectile);
		}
	}
}

function onInflictDamageEval(hit) {
	if (rank >= 2 && hit.skillId == skill.kind && (hit.stepId == Steps.Area)) {
		hit.dmgMult += hit.critChance;
	}
}

function onInflictDamage(dmg) {
	if (firedThisStep) { return; }
	if (dmg.stepId == Steps.Area && dmg.isFirstHit && !hasStatusMaxStacked(owner, Skill.Spear_Goo_Combo_Status)) {
		if (rank >= 3 && dmg.critical) {
			gainStinger(2);
		} else {
			gainStinger(1);
		}
	}
}

function onStatusEnd(s, elapsed) {
	if (elapsed && s.kind == Skill.Spear_Goo_Combo_Status) {
		destroyProjectiles();
	}
}

function tryRelease(target) {
	firedThisStep = false;
	if (hasStatusMaxStacked(owner, Skill.Spear_Goo_Combo_Status)) {
		firedThisStep = true;
		owner.tryConsumeStatus(Skill.Spear_Goo_Combo_Status);
		skill.fireProjectiles(target, null, 0.3);
	}
}

function onStep(s) {
	if (s.kind == Steps.Area && s.curCtx.aimTarget != null)
		tryRelease(s.curCtx.aimTarget);
}

function onProjectileCreated(proj) {
	hoverProjectile(proj, 3);
}


function onProjectileHit(hit) {
	if (hit.projectile != null) {
		if (checkProba(0.5)) {
			playStep(Steps.PhysicalDamage, hit.target);
		} else {
			playStep(Steps.MagicDamage, hit.target);
		}
	}
}

function onProjectileCreated(proj) {
	proj.config.returnDelay = vars.dur1;
}

function onDamageEval(hit) {
	if (rank >= 2) {
		hit.critChance += vars.chance;
	}
}

function onProjectileEnd(proj) {
	if( rank >= 3 ) {
		addStatus(owner, Skill.Spear_Goo_Skill1_Status);
	}
}

function onInflictDamage(dmg) {
	if (rank >= 2) {
		if (dmg.skillId == Skill.Spear_Goo_Skill2) {
			reduceCooldown(skill.kind, vars.time);
		}
	}
}

function onInflictDamage(dmg) {
	if(elapsedTime > 0 && (dmg.isBaseAttack || dmg.isWeaponSkill) && dmg.critical) {
		if (dmg.isMagic) {
			addStatus(dmg.target, Skill.Spear_Goo_PassiveStatus);
		}
		if (dmg.isPhysical) {
			if (dmg.target.tryConsumeStatus(Skill.Spear_Goo_PassiveStatus, dmg.sourceObject) > 0) {
				addStatus(dmg.target, Skill.Spear_Goo_Passive_Dot);
			}
		}
	}
}

function onStatusConsumed(s,stacks) {
	if (rank >= 3) {
		if (s.kind == Skill.Spear_Goo_PassiveStatus) {
			resetCooldown(Skill.Spear_Goo_Skill2);
		}
	}
}

function onDamageEval(dmg) {
	if (sourceSkill.rank >= 2) {
		if (dmg.skillId == Skill.Spear_Goo_Passive_Dot) {
			dmg.dmgMult += sourceSkill.vars.var1;
		}
	}
}

function onFirstHit(hit) {
	if (rank >= 2) {
		reduceWeaponsCooldown(vars.time);
	}

}

function onDamage(dmg) {
	if (rank >= 3 && dmg.critical && dmg.isPhysical) {
		playStep(Steps.BonusDamage, dmg.target);
	}
	if (dmg.isPhysical && dmg.isFirstHit) {
		addStatus(owner, Skill.Spear_Eruption_Combo_Status);
	}
}

function onInflictDamage(dmg) {
	if (rank>=3 && dmg.critical) {
		extendDuration(vars.time2);
	}
}

function onHit(hit) {
	if (rank >= 3 && hit.stepId == Steps.Stun) {
		playStep(Steps.ApplyStun, hit.target);
	}
}

var BUFF =  Skill.Spear_Eruption_Passive_Status;
var SHIELD = Skill.Spear_Eruption_Passive_Shield;


function onInflictDamage(dmg) {
	if (dmg.isFirstHit && (dmg.isWeaponSkill || dmg.isFinalCombo || isSkillValid(dmg.baseSkill) || isSkillValid(dmg.status?.getSourceSkill()))) {
		addStatus(owner, BUFF);
	}
	if (dmg.critical && rank >= 3 && hasStatusMaxStacked(owner, BUFF)) {
		var amount = dmg.amount * vars.var1;
		addShield(owner, SHIELD, amount);
	}
}

function isSkillValid(skill) {
	if (skill == null) { return false; }
	if (skill.isBasicAttack() || skill.isFinalAttack() || skill.isWeaponSkill()) {
		return true;
	}
	return false;
}

// function onReceiveDamage(dmg) {
// 	addStacks(-round(dmg.amount));
// }

function onFirstHit(h) {
	addStatus(owner, Skill.DS_Bladeleaf_Combo_Status);
}

function onHit(hit) {
	if (rank >= 3 && checkProba(vars.chance)) {
		addStatus(owner, Skill.DS_Bladeleaf_Combo_Status);
	}
}

function onSkillProc(ctx) {
	if(ctx.skill.isWeaponSkill()) {
		ctx.dmgMult += vars.var1;
		stop();
	}
}

function onStacksChange() {
	var diff = status.stacks - skill.getProjectiles().length;
	for (i in 0...diff) {
		playStep(Steps.Projectile);
	}
}

function onStatusEnd(s,elapsed) {
	if (s.kind == status.kind && elapsed) {
		destroyProjectiles();
	}
}

function onProjectileCreated(proj) {
	hoverProjectile(proj, status.getMaxStacks());
}

function onUseSkill(s) {
	if (s.skill.isSignature()) {
		skill.fireProjectiles(s.aimTarget);
		status.consume();
	}
}

var RECAST = Skill.DS_Bladeleaf_Skill_1Recast;

var firstCast = false;

function onUseSkill(s) {
	if (s.skillId == skill.kind) {
		firstCast = !haveRecast();
		if (firstCast) {
			addStatus(owner, RECAST, vars.time);
		} else {
			removeStatus(owner, RECAST);
		}
	}
}

function onInflictDamageEval(hit) {
	if (hit.skillId == skill.kind) {
		if (!firstCast) {
			hit.dmgMult += vars.var1;
			if (rank >= 2) {
				hit.magicArmorIgnore += 1;
			}
		}
		if (rank >= 3) {
			if (hit.targetUnit.healthRatio > vars.threshold) {
				hit.dmgMult += vars.var2;
			}
		}
	}
}

function haveRecast() {
	return owner.getStatusCount(RECAST) > 0;
}

function shouldHighlightSkill() {
	return haveRecast();
}

function checkForceRecast() {
	return haveRecast();
}

function onInflictDamage(hit) {
	if (hit.isBaseAttack || hit.isFinalCombo) {
		playStep(Steps.BonusDamage, hit.target);
	}
}

function onUseSkill(ctx) {
	if (ctx.isSkill) {
		if (!isInCooldown()) {
			ctx.magicDmgMult += vars.damage;
			consumeCooldown();
		}
	}
}

function onRegUpdate(dt) {
	enforceStatus(owner, Skill.DS_Bladeleaf_Passive_Status, !isInCooldown());
}

function onInflictDamage(dmg) {
	if (rank >= 3) {
		if (dmg.critical && dmg.baseSkill.kind != skill.kind && isInCooldown()) {
			playStep(Steps.Damage, dmg.target);
		}
	}
}

function onRegUpdate(dt) {
	if(rank >= 2) {
		var foesBuffVal = 0.;
		var enemies = getEnemiesInRange(owner, vars.range);
		foesBuffVal += enemies.length;
		setDynVal(1, foesBuffVal);
	}
}

function onInflictHit(hit) {
	if(hit.isBaseAttack) {
		var status = owner.getStatus(Skill.DA_Water_Combo_Status);
		if(status != null && status.stacks >= status.getMaxStacks() && checkProba(vars.chance)) {
			playStep(Steps.Axe);
		}
	}
}

function onInflictHit(hit) {
	if( hit.isBaseAttack) {
		if(checkProba(vars.chance) && hit.skillId != skill.kind) {
			playStep(Steps.Attack, hit.target);
		}
	}
}

function onStart(ctx) {
	if (getSkillRank(Skill.DA_Water_Skill1) >= 3) {
		addStatus(owner, Skill.DA_Water_Skill1_StatusShield);
	}
}

function onStart(app) {
	var missing = owner.maxHealth - owner.health;
	status.setShield(missing * vars.var1);
}

function onUpdate(dt) {
	if(!status.instigatorSkill.isRunning())
		stop();
}

function onInflictDamage(dmg) {
	if( dmg.isFirstHit && dmg.isBaseAttack)
		reduceCooldown(Skill.DA_Water_Skill2, vars.time);
}

function onDamageEval(hit) {
	if( rank >= 2 )
		hit.ignoreResistance = true;
}

function onKill(dmg) {
	if(rank >= 3 && dmg.skillId == Skill.DA_Water_Skill2 ) {
		var dmg = dmg.amount;
		var amount = dmg * vars.var1;
		applyHeal(owner, amount);
	}
}

function onReceiveDamage(dmg) {
	setStatus(owner, Skill.DA_Water_Passive_Status, owner.isInCombat && owner.healthRatio < vars.var1 ? 1 : 0);
	if(rank >= 3) {
		if(owner.isInCombat && owner.healthRatio < vars.var2 && !hasStatus(owner, Skill.DA_Water_Passive_Status_R3)) {
			addStatus(owner, Skill.DA_Water_Skill1_Status);
			addStatus(owner, Skill.DA_Water_Passive_Status_R3);
		}
	}
}

function onHit(hit) {
	if (rank >= 3 && hit.target.hasStatus(Skill.DM_Multispin_Combo_Status)) {
		if (hit.stepId == Steps.FirstHit) {
			playStep(Steps.BonusDamage, hit.target);
		}
	}
}

function onReceiveDamageEval(dmg) {
	dmg.dmgMult += vars.damage;
}

var lastHitTime = 0.;
var recasting = false;

function onHit(hit) {
	stampRecast();
	addStatusDuration(owner, Skill.DM_Multispin_Skill1_Recast, vars.time);
	if (rank >= 3 && recasting) {
		addStatus(hit.target, Skill.DM_Multispin_Skill1_Status);
	}
}

function onClientHit(hit) {
	stampRecast();
}

