function onStartConduit() {
	var instanceIndex = getSkillInstanceIndex();
	if(instanceIndex < 0) return;

    var fanRadius = 2.5;
    var fanAmplitude = 240;
    var shotDelay = 0.1;

	var target = getActiveSkill()?.aimTarget;
	if (target == null) target = owner.getTarget();

    var count = getSkillInstanceCount();
    if (target != null) {
        var projStep = getStepById(Steps.Projectile);
        var startPos = projStep.getProjectileStart();

        var interProgress = 1 / (count+1);
		var pos = startPos;
		if (count > 1) {
			for (i in 0...instanceIndex + 1) {
				pos = p3DAdd(startPos, getFanFacingPos((i+1) * interProgress, fanAmplitude, fanRadius, p2DTo3D( p2DSub(target.pos2D, owner.pos2D)) ) );
			}
		}
		wait(instanceIndex * shotDelay, function() {
			projStep.generateProjectile(target, pos);
		});
    }
}

