	if (step.kind == Steps.Trigger) {
		if (canBlinkBack() && canReblink) {
			removeSkillStatus(Skill.Mage_Blink_Mastery2_Position);
			canReblink = false;
		}
	}
	if (hasMastery(Mastery.Mage_Blink_M2) ) {
		if (step.kind == Steps.Start) {
			if (!haveReblinkStatus()) {
				addStatusDuration(owner, Skill.Mage_Blink_Mastery2_Position, skill.vars.dur1);
			} else {
