	if (step.kind == Steps.Trigger) {
		if (canBlinkBack() && canReblink) {
			localPlayStep(Steps.TeleportBack, null, returnPosition);
			canReblink = false;
		} else {
			localPlayStep(Steps.Teleport);
		}
	}
	if (step.kind == Steps.Start) {
		if (!haveReblinkStatus()) {
			returnPosition = skill.ownerUnit.position.clone();

		} else {
			canReblink = true;
		}
	}

}

