function onSkillProc(ctx) {
	if( ctx.skill.isWeaponSkill() ) {

    var fanRadius = 2.5;
    var fanAmplitude = 240;
    var shotDelay = 0.1;

	var target = getActiveSkill()?.aimTarget;
	if (target == null) target = owner.getTarget();

    var count = 1;

    if (target != null) {
        var projStep = getStepById(Steps.Projectile);
        var startPos = projStep.getProjectileStart();

        var interProgress = 1 / (count+1);
        for (i in 0...count) {
            var pos = startPos;
            if (count > 1) {
                pos = p3DAdd(startPos, getFanFacingPos((i+1) * interProgress, fanAmplitude, fanRadius, p2DTo3D( p2DSub(target.pos2D, owner.pos2D)) ) );
            }
            wait(i * shotDelay, function() {
                projStep.generateProjectile(target, pos);
            });
        }
    }
	stop();
	}
}

var prevTime = -1.;

function onUpdate(dt) {
	var curTime = owner.getTimeInCombat();
	if (curTime >= 0 && prevTime < 0) {
		prevTime = 0;
		if( !hasStatus(owner, Skill.PrismaticPearl_Status) && !hasStatus(owner, Skill.PrismaticPearl_Status2) ) {
			addStatus(owner, Skill.PrismaticPearl_Status);
		}
	}
	if (curTime - prevTime >= vars.time) {
		prevTime += vars.time;
		if( hasStatus(owner, Skill.PrismaticPearl_Status))  {
			addStatus(owner, Skill.PrismaticPearl_Status2);
			removeStatus(owner, Skill.PrismaticPearl_Status);
		}
		else if ( hasStatus(owner, Skill.PrismaticPearl_Status2)) {
			addStatus(owner, Skill.PrismaticPearl_Status);
			removeStatus(owner, Skill.PrismaticPearl_Status2);
		}
	}
	if (curTime < prevTime)
		prevTime = curTime;
}

