function onInflictDamageEval(hit) {
	if (hit.skill?.isBaseAttack()) {
		var inRange = getEnemiesInRange(owner, vars.range);
		if (inRange.length >= vars.var1)
			hit.dmgMult += vars.damage;
	}
}

function onInflictDamageEval(hit) {
	if (hit.skill?.isBasicAttack()) {
		if (p3DDist(owner.position, hit.target.position) > vars.range)
			hit.dmgMult += vars.damage;
	}
}

function onSkillProc(hit) {
	if (hit.skill?.isBaseAttack()) {
		if (checkProba(vars.chance))
			reduceWeaponsCooldown(vars.time, owner);
	}
}

function onInflictDamageEval(hit) {
	if (hit.skill?.isBasicAttack()) {
		if (p3DDist(owner.position, hit.target.position) > vars.range)
			hit.critChance += vars.chance;
	}
}

function onReceiveDamageEval(hit) {
	hit.dmgMult -= vars.damage;
}

function onStep(s) {
    if(s.kind == Steps.End)
        kickDriver();
}

function onStep(s) {
    if(ownerHero != null && s.kind == Steps.End) {
		var loc = ownerHero.getTeleportLocation(skill.getSourceItem()?.kind);
		if (loc == null)
			loc = ownerHero.getRespawnPoint();
		ownerHero.teleport(loc);
	}
}

function checkEnabled() {
	if( ownerHero.player.progress.checkAddToCollection(skill.originItem) != Ok )
		return Reason.ItemAlreadyOwned;
	return Ok;
}

function onStep(s) {
    if(s.kind == Steps.End)
		ownerHero.player.progress.addToCollection(skill.originItem);
}

