function onSkillObjectEvent( obj, ev, target ) {
	if( ev == SkillObjectEvent.Spawn || ev == SkillObjectEvent.Pickup ) {
		obj.bounceTo(getGroundRandomPosInRangeFromPt(obj.getOrigin(), 10, 3), 5, (o) -> { });
	}
	if( ev == SkillObjectEvent.Pickup ) {
		addStatus(target, Skill.Activity_BallonBouncing_StatusCounter);
	}
	if( ev == SkillObjectEvent.End ) {
		removeStatus(owner, Skill.Activity_BallonBouncing_StatusCounter);
	}
}

var seq = 0.;
function onProjectileCreated(proj) {
	var randX = random(-2, 2);
	var randY = random(-2, 2);
	var fanAmplitude = 130;
	var fanRadius = 2;
	var pos = getFanFacingPos(seq / 4, fanAmplitude, fanRadius, WORLD_RIGHT);
	seq += 1;
	seq %= 5;
	proj.startHover(pos.x, pos.y, pos.z + 2);
}

function onSkillProc(ctx) {
	if (ctx.skillId != skill.kind) {
		skill.fireProjectiles(ctx.aimTarget, ctx.aimPosition);
	}
}
